package com.mfg.erp.service;
import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.erp.dto.SalesOrderCommand;import com.mfg.erp.entity.*;import com.mfg.erp.repo.*;import com.mfg.mdm.entity.*;import com.mfg.mdm.repo.*;import com.mfg.mdm.service.MasterDataService;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;
@Service @RequiredArgsConstructor public class SalesOrderService{private final SalesOrderRepository orders;private final SalesOrderLineRepository lines;private final CustomerRepository customers;private final MaterialRepository materials;private final MasterDataService master;
 @Transactional public SalesOrder create(SalesOrderCommand c){if(orders.existsBySalesOrderNo(c.salesOrderNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"销售订单号已存在");Customer customer=customers.findByCustomerCode(c.customerCode()).orElseThrow(()->BizException.of(ErrorCode.MASTER_DATA_NOT_FOUND,"客户不存在"));master.assertConsumable(customer,"ERP 销售订单");SalesOrder o=new SalesOrder();o.setSalesOrderNo(c.salesOrderNo());o.setCustomerCode(customer.getCustomerCode());o.setCustomerName(customer.getCustomerName());o.setOrderDate(LocalDate.now());o.setDeliveryDate(c.deliveryDate());o.setSourceOpportunityNo(c.sourceOpportunityNo());o.setRemark(c.remark());o.setSalesUser(CurrentUser.usernameOrSystem());o.setDeptCode(CurrentUser.get().getDeptCode());o.setTotalAmount(BigDecimal.ZERO);o=orders.save(o);BigDecimal total=BigDecimal.ZERO;for(var x:c.lines()){Material m=materials.findByMaterialCode(x.materialCode()).orElseThrow(()->BizException.of(ErrorCode.MASTER_DATA_NOT_FOUND,"物料不存在："+x.materialCode()));master.assertConsumable(m,"ERP 销售订单");SalesOrderLine l=new SalesOrderLine();l.setSalesOrderNo(o.getSalesOrderNo());l.setLineNo(x.lineNo());l.setMaterialCode(m.getMaterialCode());l.setMaterialName(m.getMaterialName());l.setOrderQty(x.orderQty());l.setUnitCode(x.unitCode()==null?m.getBaseUnitCode():x.unitCode());l.setUnitPrice(x.unitPrice());l.setLineAmount(x.orderQty().multiply(x.unitPrice()).setScale(2,RoundingMode.HALF_UP));l.setDeliveryDate(c.deliveryDate());lines.save(l);total=total.add(l.getLineAmount());}o.setTotalAmount(total);return orders.save(o);}
 @Transactional public SalesOrder confirm(Long id){SalesOrder o=orders.findById(id).orElseThrow(()->BizException.notFound("销售订单",id));if(!"DRAFT".equals(o.getStatus()))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"只有草稿订单可确认");if(lines.findBySalesOrderNoOrderByLineNo(o.getSalesOrderNo()).isEmpty())throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"订单没有明细");o.setStatus("CONFIRMED");return orders.save(o);}
}
